def count_up_to(n):
    """Implement a function that takes an non-negative integer and returns an array of the first n
    integers that are prime numbers and less than n.
    for example:
    count_up_to(5) => [2,3]
    count_up_to(11) => [2,3,5,7]
    count_up_to(0) => []
    count_up_to(20) => [2,3,5,7,11,13,17,19]
    """
    if n <= 2:
        return []
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False
    for p in range(2, int(n**0.5) + 1):
        if is_prime[p]:
            for multiple in range(p * p, n, p):
                is_prime[multiple] = False
    return [i for i in range(2, n) if is_prime[i]]

def histogram(test):
    # Split the input string into individual characters
    letters = test.split()

    # If no letters, return empty dictionary
    if not letters:
        return {}

    # Count occurrences of each letter
    counts = {letter: letters.count(letter) for letter in letters}

    # Find the maximum count
    max_count = max(counts.values())

    # Return only letters with the maximum count
    return {letter: count for letter, count in counts.items() if count == max_count}

def max_fill(grid, capacity):
    total_water = sum(sum(row) for row in grid)
    return (total_water + capacity - 1) // capacity

