def even_odd_count(num):
    even = 0
    odd = 0
    for digit in str(abs(num)):
        if int(digit) % 2 == 0:
            even += 1
        else:
            odd += 1
    return (even, odd)

def find_max(words):
    if not words:
        return ""
    best_word = words[0]
    max_unique = len(set(best_word))
    for word in words[1:]:
        unique = len(set(word))
        if unique > max_unique:
            best_word = word
            max_unique = unique
        elif unique == max_unique:
            if word < best_word:
                best_word = word
    return best_word

